    incidents: List[HazardIncident] = []
    for item in data:
        bbox = BoundingBox(
            xmin=0.30,
            ymin=0.45,
            xmax=0.70,
            ymax=0.85,
            label=item["hazard_type"].value,
            confidence=0.94 if item["severity"] == SeverityLevel.CRITICAL else (0.88 if item["severity"] == SeverityLevel.HIGH else 0.81),
        )
        vis_det = VisualDetection(
            hazard_type=item["hazard_type"],
            confidence=bbox.confidence,
            bbox=bbox,
            estimated_area_sqm=item["area_sqm"],
            estimated_depth_cm=item["depth_cm"],
        )
        telemetry = TelemetrySample(
            timestamp=item["detected_at"],
            latitude=item["latitude"],
            longitude=item["longitude"],
            speed_kmh=48.5,
            acc_x_g=0.04 if item["is_bump"] else 0.01,
            acc_y_g=0.03 if item["is_bump"] else 0.01,
            acc_z_g=item["acc_z"],
            vertical_jerk_g_s=round(abs(item["acc_z"] - 1.0) * 12.0, 1),
            iri_roughness_m_km=round(item["depth_cm"] * 0.45 + 2.5, 2) if item["depth_cm"] > 0 else 2.1,
        )
        acoustic = AcousticFeature(
            timestamp=item["detected_at"],
            dominant_freq_hz=820.0 if item["is_bump"] else 240.0,
            impact_energy_db=item["acoustic_db"],
            acoustic_anomaly_score=0.88 if item["is_bump"] else 0.15,
            signature_type="wet_tire_thud" if item["precip"] > 0 else "dry_impact",
        )
        citizen = CitizenReport(
            report_id=f"CIT-{item['id']}",
            timestamp="2026-08-25T13:45:00Z",
            text_content=f"Citizen report: {item['title']} observed at {item['road_name']}",
            reporter_urgency=5 if item["severity"] == SeverityLevel.CRITICAL else (4 if item["severity"] == SeverityLevel.HIGH else 3),
            source="SadakSuraksha_Citizen_Portal",
            citizen_category="Road Distress / Safety Hazard",
        )
        env = EnvironmentalContext(
            temperature_c=28.5,
            precipitation_mm=item["precip"],
            freeze_thaw_cycles_24h=0,
            aadt_traffic_volume=item["aadt"],
            is_emergency_route=item["is_emergency"],
            is_public_transit_corridor=item["is_transit"],
        )

        fusion_res = fusion_engine.fuse(
            visual=vis_det,
            telemetry=telemetry,
            acoustic=acoustic,
            citizen_report=citizen,
            env_context=env,
        )

        priority_res = prioritization_engine.calculate_priority_metrics(
            hazard_type=item["hazard_type"],
            severity=item["severity"],
            fusion=fusion_res,
            road_class=item["road_class"],
            env_context=env,
        )

        trace = generate_sample_telemetry_trace(
            acc_z_peak=item["acc_z"],
            is_bump=item["is_bump"],
        )

        incident = HazardIncident(
            id=item["id"],
            title=item["title"],
            hazard_type=item["hazard_type"],
            severity=item["severity"],
            state=item["state"],
            city=item["city"],
            road_id=item["road_id"],
            road_name=item["road_name"],
            road_class=item["road_class"],
            latitude=item["latitude"],
            longitude=item["longitude"],
            address=item["address"],
            detected_at=item["detected_at"],
            visual_detections=[vis_det],
            telemetry=telemetry,
            acoustic=acoustic,
            citizen_report=citizen,
            env_context=env,
            fusion=fusion_res,
            priority=priority_res,
            status=item["status"],
            telemetry_trace=trace,
        )
        incidents.append(incident)

    ranked = sorted(incidents, key=lambda x: x.priority.raw_risk_score, reverse=True)
    for idx, inc in enumerate(ranked, 1):
        inc.priority.final_priority_rank = idx

    return ranked
